 for(int osc=0;osc<3;++osc){p.loadPreset(0);p.set("env1r",.01f);String error,id="osc"+String(osc+1);if(!p.loadOscillatorAsset(osc,sfz,4,error))return fail("multi load");{auto assets=std::atomic_load(&p.importedAssets);for(float hidden:{.25f,.65f,.99f}){VoiceExtras reference,shifted;reference.start(assets->expansion,48000,48,1,0);shifted.start(assets->expansion,48000,48,1,0);OscSettings settings;settings.sampleStart=0;settings.sampleEnd=1;float attack=0;for(int n=0;n<512;++n){auto normal=reference.sampleOsc(osc,0,MidiMessage::getMidiNoteInHertz(48),4,0,1,&settings);auto other=shifted.sampleOsc(osc,0,MidiMessage::getMidiNoteInHertz(48),4,hidden,1,&settings);if(std::abs(normal[0]-other[0])>1.e-7f||std::abs(normal[1]-other[1])>1.e-7f)return fail("hidden wavetable position cuts multisample attack");if(n<16)attack=jmax(attack,std::abs(other[0]));}if(attack<.1f)return fail("multisample attack missing");}}p.set(id+"pos",.65f);{SynthGraph view(p,SynthGraph::Osc,osc);view.setSize(244,148);MouseWheelDetails wheel;wheel.deltaY=.5f;view.mouseWheelMove(event(view,{60,40}),wheel);if(std::abs(p.value(id+"pos")-.65f)>.0001f||p.value(id+"timbre")<=0)return fail("multisample wheel modifies hidden sample offset");p.set(id+"timbre",0);}p.set(id+"enabled",1);p.set(id+"level",.8f);p.set(id+"voices",1);p.set(id+"pos",.65f);p.set(id+"loop",1);p.set(id+"detune",0);p.set(id+"sampleStart",.2f);p.set(id+"sampleEnd",1);midi.addEvent(MidiMessage::noteOn(1,48,(uint8)100),0);run();int low=latest();if(low<0||p.graphTelemetry->oscVoices[low].region[osc].load()!=0)return fail("low region selection");float at=p.graphTelemetry->samplePlayheads[low][osc].load();if(std::abs(at-(.2f+512.f/96000))>.0002f)return fail("multi playhead start");SynthGraph graph(p,SynthGraph::Osc,osc);graph.setSize(244,148);auto lowImage=graph.createComponentSnapshot(graph.getLocalBounds());save(graph,"OSC-"+String(osc+1)+"-Multi-Low");midi.addEvent(MidiMessage::noteOn(1,72,(uint8)100),0);run();int high=latest();if(high==low||p.graphTelemetry->oscVoices[high].region[osc].load()!=1)return fail("high region selection");auto highImage=graph.createComponentSnapshot(graph.getLocalBounds());int differences=0;for(int y=20;y<115;++y)for(int x=5;x<239;++x)differences+=lowImage.getPixelAt(x,y)!=highImage.getPixelAt(x,y);if(differences<1000)return fail("multisample waveform did not follow selected sample");save(graph,"OSC-"+String(osc+1)+"-Multi-High");midi.addEvent(MidiMessage::allSoundOff(1),0);run(20);p.set(id+"timbre",24);midi.addEvent(MidiMessage::noteOn(1,48,(uint8)100),0);run();if(p.graphTelemetry->oscVoices[latest()].region[osc].load()!=1)return fail("timbre region remap telemetry");midi.addEvent(MidiMessage::allSoundOff(1),0);run(20);}
